@@ -1,73 +0,0 @@
-#!/usr/bin/env node
-import { readFileSync } from "node:fs";
-import { resolve } from "node:path";
-import {
-  agentRmnMessage,
-  extractRmnPart,
-  parseA2aMessage,
-} from "@red-cup-engineering/a2a-rmn-part-service";
-import { handleProductionProfileCarrier } from "./bound-git-profile.js";
-
-function required(environment, name) {
-  const value = environment[name];
-  if (typeof value !== "string" || value.length === 0) {
-    throw new Error(`${name} is required for activated coordinator ingress`);
-  }
-  return value;
-}
-
-export async function executeBoundGitProfileA2aMessage(source, {
-  environment = process.env,
-  handle = handleProductionProfileCarrier,
-} = {}) {
-  const message = parseA2aMessage(
-    typeof source === "string" || Buffer.isBuffer(source)
-      ? JSON.parse(Buffer.from(source).toString("utf8"))
-      : source,
-  );
-  const { bytes } = extractRmnPart(message.parts);
-  const inputJws = message.metadata?.boundGitProfileAuthorization?.inputJws;
-  if (!inputJws) throw new Error("signed Git profile authorization is required");
-  const signed = await handle(bytes, {
-    routesFile: required(environment, "BOUND_GIT_COORDINATOR_ROUTES"),
-    inputJws,
-    privateKeyPem: readFileSync(
-      resolve(required(environment, "BOUND_GIT_COORDINATOR_SIGNING_KEY")),
-      "utf8",
-    ),
-    signingKid: required(environment, "BOUND_GIT_COORDINATOR_SIGNING_KID"),
-    signingJwks: required(environment, "BOUND_GIT_COORDINATOR_SIGNING_JWKS"),
-    descriptor: JSON.parse(
-      readFileSync(
-        resolve(required(environment, "BOUND_GIT_COORDINATOR_DESCRIPTOR")),
-        "utf8",
-      ),
-    ),
-    dataRoot: required(environment, "BOUND_GIT_COORDINATOR_DATA_ROOT"),
-  });
-  const response = agentRmnMessage(signed.bytes);
-  response.metadata = {
-    ...response.metadata,
-    jws: signed.jws,
-    ...(signed.deviceReceipt === undefined
-      ? {}
-      : {
-          deviceReceiptJws: signed.deviceReceiptJws,
-          profileEvidence: signed.profileEvidence,
-          profileEvidenceJws: signed.profileEvidenceJws,
-        }),
-  };
-  return response;
-}
-
-async function readStandardInput() {
-  const chunks = [];
-  for await (const chunk of process.stdin) chunks.push(chunk);
-  return Buffer.concat(chunks);
-}
-
-if (import.meta.url === `file://${process.argv[1]}`) {
-  process.stdout.write(
-    `${JSON.stringify(await executeBoundGitProfileA2aMessage(await readStandardInput()))}\n`,
-  );
-}

@@ -1,287 +0,0 @@
-import { readFileSync } from "node:fs";
-import {
-  agentCardSignatureEvidence,
-  discoverSignedAgentCard,
-} from "@red-cup-engineering/a2a-agent-card-discovery-service";
-import {
-  decodeProtectedHeader,
-  flattenedVerify,
-  FlattenedSign,
-  importJWK,
-  importPKCS8,
-} from "jose";
-import { readProviderAllocation } from "./bound-git-profile-store.js";
-import {
-  decodeCarrier,
-  validatePrivateIndexReleaseBinding,
-} from "./bound-git-profile-wire.js";
-
-export function readCoordinatorRoutes(path) {
-  const source = JSON.parse(readFileSync(path, "utf8"));
-  if (source?.version !== 1 || !Array.isArray(source.routes)) {
-    throw new Error("actor-route-drift");
-  }
-  const routes = new Map();
-  let prior = "";
-  for (const route of source.routes) {
-    if (
-      !route ||
-      Object.keys(route).sort().join() !== "account,actor,agentCardUrl" ||
-      typeof route.actor !== "string" ||
-      route.actor <= prior ||
-      routes.has(route.actor) ||
-      !/^https?:\/\//u.test(route.agentCardUrl) ||
-      !(
-        route.account === null ||
-        /^eip155:31337:0x[0-9a-fA-F]{40}$/u.test(route.account)
-      )
-    ) {
-      throw new Error("actor-route-drift");
-    }
-    prior = route.actor;
-    routes.set(route.actor, Object.freeze({ ...route }));
-  }
-  return routes;
-}
-
-export async function verifyGitProfileCaller({
-  routes,
-  operation,
-  bytes,
-  jws,
-  fetch: fetchImpl = globalThis.fetch,
-  discover = discoverSignedAgentCard,
-}) {
-  const route = routes.get(operation.gitActor);
-  if (!route || route.account !== operation.gitAccount) {
-    throw new Error("actor-route-drift");
-  }
-  const card = await discover({
-    agentUrl: route.agentCardUrl,
-    fetch: fetchImpl,
-    signal: new AbortController().signal,
-  });
-  const evidence = agentCardSignatureEvidence(card);
-  if (
-    operation.gitCardId !== evidence.card ||
-    operation.gitCardSignatureId !== evidence.signature ||
-    operation.gitKid !== evidence.kid ||
-    operation.gitJwks !== evidence.jwks
-  ) {
-    throw new Error("actor-route-drift");
-  }
-  const header = decodeProtectedHeader(jws);
-  if (
-    Object.keys(header).sort().join() !== "alg,jku,kid,typ" ||
-    header.typ !== "JOSE" ||
-    header.kid !== evidence.kid ||
-    header.alg !== evidence.algorithm ||
-    header.jku !== evidence.jwks
-  ) {
-    throw new Error("actor-route-drift");
-  }
-  const response = await fetchImpl(evidence.jwks, {
-    headers: { Accept: "application/jwk-set+json, application/json" },
-    signal: new AbortController().signal,
-  });
-  if (!response.ok) throw new Error("jwks-unavailable");
-  const jwks = await response.json();
-  const matches = (jwks.keys ?? []).filter(
-    (key) =>
-      key.kid === header.kid &&
-      key.alg === header.alg &&
-      !Object.hasOwn(key, "d"),
-  );
-  if (matches.length !== 1) throw new Error("actor-route-drift");
-  const verified = await flattenedVerify(
-    {
-      ...jws,
-      payload: jws.payload ?? Buffer.from(bytes).toString("base64url"),
-    },
-    await importJWK(matches[0], header.alg),
-  );
-  if (!Buffer.from(verified.payload).equals(Buffer.from(bytes))) {
-    throw new Error("binding-mismatch");
-  }
-}
-
-async function discoverRouteEvidence({
-  routes,
-  actor,
-  fetch: fetchImpl = globalThis.fetch,
-  discover = discoverSignedAgentCard,
-}) {
-  const route = routes.get(actor);
-  if (!route) throw new Error("actor-route-drift");
-  const card = await discover({
-    agentUrl: route.agentCardUrl,
-    fetch: fetchImpl,
-    signal: new AbortController().signal,
-  });
-  return Object.freeze({
-    route,
-    evidence: agentCardSignatureEvidence(card),
-  });
-}
-
-function requireReceiverEvidence(binding, evidence) {
-  if (
-    binding.receiverCardId !== evidence.card ||
-    binding.receiverCardSignatureId !== evidence.signature ||
-    binding.receiverKid !== evidence.kid ||
-    binding.receiverJwks !== evidence.jwks
-  ) {
-    throw new Error("actor-route-drift");
-  }
-}
-
-async function verifyIncludedJws({
-  bytes,
-  jws,
-  evidence,
-  fetch: fetchImpl = globalThis.fetch,
-}) {
-  const header = decodeProtectedHeader(jws);
-  if (
-    Object.keys(header).sort().join() !== "alg,jku,kid,typ" ||
-    header.typ !== "JOSE" ||
-    header.kid !== evidence.kid ||
-    header.alg !== evidence.algorithm ||
-    header.jku !== evidence.jwks ||
-    typeof jws.payload !== "string" ||
-    !Buffer.from(jws.payload, "base64url").equals(Buffer.from(bytes))
-  ) {
-    throw new Error("actor-route-drift");
-  }
-  const response = await fetchImpl(evidence.jwks, {
-    headers: { Accept: "application/jwk-set+json, application/json" },
-    signal: new AbortController().signal,
-  });
-  if (!response.ok) throw new Error("jwks-unavailable");
-  const jwks = await response.json();
-  const matches = (jwks.keys ?? []).filter(
-    (key) =>
-      key.kid === header.kid &&
-      key.alg === header.alg &&
-      !Object.hasOwn(key, "d"),
-  );
-  if (matches.length !== 1) throw new Error("actor-route-drift");
-  const verified = await flattenedVerify(jws, await importJWK(matches[0], header.alg));
-  if (!Buffer.from(verified.payload).equals(Buffer.from(bytes))) {
-    throw new Error("binding-mismatch");
-  }
-}
-
-export async function verifyReceiverProfileEvidence({
-  routes,
-  operation,
-  dataRoot,
-  fetch,
-  discover,
-}) {
-  if (operation.kind === "prepare-profile-operation") {
-    const { evidence } = await discoverRouteEvidence({
-      routes,
-      actor: operation.receiverActor,
-      fetch,
-      discover,
-    });
-    requireReceiverEvidence(operation, evidence);
-    return;
-  }
-  if (operation.kind !== "retire-profile-operation") return;
-  const { allocation } = readProviderAllocation({
-    root: dataRoot,
-    allocationId: operation.allocationId,
-  });
-  const { result } = validatePrivateIndexReleaseBinding({
-    operation,
-    allocation,
-  });
-  const { evidence } = await discoverRouteEvidence({
-    routes,
-    actor: allocation.receiverActor,
-    fetch,
-    discover,
-  });
-  requireReceiverEvidence(allocation, evidence);
-  if (
-    result.receiverCardId !== evidence.card ||
-    result.receiverCardSignatureId !== evidence.signature ||
-    result.receiverKid !== evidence.kid ||
-    result.receiverJwks !== evidence.jwks
-  ) {
-    throw new Error("actor-route-drift");
-  }
-  await verifyIncludedJws({
-    bytes: operation.releaseResultBytes,
-    jws: operation.releaseResultJws,
-    evidence,
-    fetch,
-  });
-  decodeCarrier("EvidenceResult", operation.releaseResultBytes);
-}
-
-export async function signProfileCarrier({
-  bytes,
-  privateKeyPem,
-  kid,
-  jwks,
-}) {
-  const key = await importPKCS8(privateKeyPem, "EdDSA");
-  return new FlattenedSign(bytes)
-    .setProtectedHeader({ alg: "EdDSA", kid, jku: jwks, typ: "JOSE" })
-    .sign(key);
-}
-
-export function createCoordinatorProductionContext({
-  routesFile,
-  inputJws,
-  privateKeyPem,
-  signingKid,
-  signingJwks,
-  descriptor,
-  dataRoot,
-  fetch,
-  discover,
-}) {
-  if (
-    typeof routesFile !== "string" ||
-    typeof inputJws !== "object" ||
-    typeof privateKeyPem !== "string" ||
-    typeof signingKid !== "string" ||
-    typeof signingJwks !== "string"
-  ) {
-    throw new Error("coordinator-production-boundary-unavailable");
-  }
-  const routes = readCoordinatorRoutes(routesFile);
-  return Object.freeze({
-    descriptor,
-    dataRoot,
-    async authenticate(operation, bytes) {
-      await verifyGitProfileCaller({
-        routes,
-        operation,
-        bytes,
-        jws: inputJws,
-        fetch,
-        discover,
-      });
-      await verifyReceiverProfileEvidence({
-        routes,
-        operation,
-        dataRoot,
-        fetch,
-        discover,
-      });
-    },
-    async signResult(bytes) {
-      return signProfileCarrier({
-        bytes,
-        privateKeyPem,
-        kid: signingKid,
-        jwks: signingJwks,
-      });
-    },
-  });
-}

@@ -1,377 +0,0 @@
-import { decodeSemantic, normalizeCarrier, semanticBytes, semanticId } from "@red-cup-engineering/relation-model-notation-cbor-codec";
-import {
-  closeSync,
-  constants,
-  existsSync,
-  linkSync,
-  lstatSync,
-  mkdirSync,
-  openSync,
-  readFileSync,
-  readdirSync,
-  unlinkSync,
-  writeFileSync,
-  fsyncSync,
-} from "node:fs";
-import { createHash } from "node:crypto";
-import { dirname, join } from "node:path";
-
-function token(value) {
-  return createHash("sha256").update(String(value)).digest("base64url");
-}
-
-function journalPath(root, operationId) {
-  return join(root, "profile-operations", token(operationId));
-}
-
-function parseStoredJson(source) {
-  return JSON.parse(source, (_key, value) =>
-    value &&
-    Object.keys(value).length === 1 &&
-    typeof value.$bytes === "string"
-      ? Buffer.from(value.$bytes, "base64url")
-      : value,
-  );
-}
-
-function readJournal(path) {
-  try {
-    return readdirSync(path)
-      .filter((name) => /^\d{8}\.json$/u.test(name))
-      .sort()
-      .map((name) => parseStoredJson(readFileSync(join(path, name), "utf8")));
-  } catch (error) {
-    if (error.code === "ENOENT") return [];
-    throw error;
-  }
-}
-
-function fsyncDirectory(path) {
-  const descriptor = openSync(path, "r");
-  try {
-    fsyncSync(descriptor);
-  } finally {
-    closeSync(descriptor);
-  }
-}
-
-function mkdirDurably(path) {
-  if (existsSync(path)) return;
-  const parent = dirname(path);
-  if (parent !== path) mkdirDurably(parent);
-  try {
-    mkdirSync(path, { mode: 0o700 });
-  } catch (error) {
-    if (error.code !== "EEXIST") throw error;
-  }
-  fsyncDirectory(path);
-  fsyncDirectory(parent);
-}
-
-function writeImmutable(path, value) {
-  const directory = dirname(path);
-  mkdirDurably(directory);
-  const temporary = join(
-    directory,
-    `.tmp-${process.pid}-${Date.now()}-${createHash("sha256").update(semanticBytes(value)).digest("hex")}`,
-  );
-  const body = `${JSON.stringify(value, (_key, item) => {
-    if (item instanceof Uint8Array) {
-      return { $bytes: Buffer.from(item).toString("base64url") };
-    }
-    if (
-      item?.type === "Buffer" &&
-      Array.isArray(item.data) &&
-      item.data.every(Number.isSafeInteger)
-    ) {
-      return { $bytes: Buffer.from(item.data).toString("base64url") };
-    }
-    return item;
-  })}\n`;
-  const descriptor = openSync(
-    temporary,
-    constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW,
-    0o600,
-  );
-  try {
-    writeFileSync(descriptor, body);
-    fsyncSync(descriptor);
-  } finally {
-    closeSync(descriptor);
-  }
-  try {
-    linkSync(temporary, path);
-  } catch (error) {
-    if (
-      error.code !== "EEXIST" ||
-      readFileSync(path, "utf8") !== body
-    ) throw error;
-  } finally {
-    unlinkSync(temporary);
-  }
-  fsyncDirectory(directory);
-}
-
-function writeImmutableBytes(path, bytes) {
-  const directory = dirname(path);
-  mkdirDurably(directory);
-  const temporary = join(
-    directory,
-    `.tmp-${process.pid}-${Date.now()}-${createHash("sha256").update(bytes).digest("hex")}`,
-  );
-  const descriptor = openSync(
-    temporary,
-    constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | constants.O_NOFOLLOW,
-    0o600,
-  );
-  try {
-    writeFileSync(descriptor, bytes);
-    fsyncSync(descriptor);
-  } finally {
-    closeSync(descriptor);
-  }
-  try {
-    linkSync(temporary, path);
-  } catch (error) {
-    if (
-      error.code !== "EEXIST" ||
-      lstatSync(path).isSymbolicLink() ||
-      !readFileSync(path).equals(Buffer.from(bytes))
-    ) {
-      throw error;
-    }
-  } finally {
-    unlinkSync(temporary);
-  }
-  fsyncDirectory(directory);
-}
-
-const ALLOCATION_KEYS = Object.freeze([
-  "type",
-  "version",
-  "prepareOperationId",
-  "publicPrepareRequestId",
-  "gitActor",
-  "gitAccount",
-  "gitCardId",
-  "gitCardSignatureId",
-  "gitKid",
-  "gitJwks",
-  "coordinatorActor",
-  "coordinatorAccount",
-  "coordinatorCardId",
-  "coordinatorCardSignatureId",
-  "coordinatorKid",
-  "coordinatorJwks",
-  "receiverActor",
-  "receiverCardId",
-  "receiverCardSignatureId",
-  "receiverKid",
-  "receiverJwks",
-  "repositoryId",
-  "receiverRootId",
-  "evidenceRootId",
-  "taskId",
-  "workOrderId",
-  "journalId",
-  "sequence",
-  "privateIndexId",
-  "expectedOldHead",
-  "declaredRef",
-  "descriptorId",
-  "createdAt",
-]);
-
-function exactCarrier(value, keys, type) {
-  const normalized = normalizeCarrier(value);
-  if (
-    normalized?.type !== type ||
-    normalized.version !== 1 ||
-    Object.keys(normalized).sort().join("\0") !== keys.slice().sort().join("\0")
-  ) {
-    throw new Error("exact-key-mismatch");
-  }
-  return Object.freeze(normalized);
-}
-
-function allocationPath(root, allocationId) {
-  return join(root, "allocations", `${token(allocationId)}.cbor`);
-}
-
-export function writeProviderAllocation({ root, allocation }) {
-  const normalized = exactCarrier(
-    allocation,
-    ALLOCATION_KEYS,
-    "ProviderPrivateIndexAllocation",
-  );
-  const allocationId = semanticId(normalized);
-  const bytes = semanticBytes(normalized);
-  writeImmutableBytes(allocationPath(root, allocationId), bytes);
-  return Object.freeze({ allocationId, allocation: normalized, bytes });
-}
-
-export function readProviderAllocation({ root, allocationId }) {
-  const path = allocationPath(root, allocationId);
-  if (lstatSync(path).isSymbolicLink()) throw new Error("allocation-drift");
-  const bytes = readFileSync(path);
-  const allocation = exactCarrier(
-    decodeSemantic(bytes),
-    ALLOCATION_KEYS,
-    "ProviderPrivateIndexAllocation",
-  );
-  if (
-    semanticId(allocation) !== allocationId ||
-    !Buffer.from(semanticBytes(allocation)).equals(bytes)
-  ) {
-    throw new Error("allocation-drift");
-  }
-  return Object.freeze({ allocationId, allocation, bytes });
-}
-
-export function writeCarrierObject({ root, directory, id, carrier, family }) {
-  const bytes = semanticBytes(carrier);
-  if (semanticId(carrier) !== id) throw new Error(`${family}-identity-drift`);
-  const path = join(root, directory, `${token(id)}.cbor`);
-  writeImmutableBytes(path, bytes);
-  return Object.freeze({ id, carrier: Object.freeze(carrier), bytes, path });
-}
-
-export function readCarrierObject({ root, directory, id, normalize }) {
-  const path = join(root, directory, `${token(id)}.cbor`);
-  if (lstatSync(path).isSymbolicLink()) throw new Error("carrier-object-drift");
-  const bytes = readFileSync(path);
-  const carrier = normalize(decodeSemantic(bytes));
-  if (
-    semanticId(carrier) !== id ||
-    !Buffer.from(semanticBytes(carrier)).equals(bytes)
-  ) {
-    throw new Error("carrier-object-drift");
-  }
-  return Object.freeze({ id, carrier, bytes, path });
-}
-
-function retiredMarkerPath(root, operationId) {
-  return join(root, "retired-markers", `${token(operationId)}.cbor`);
-}
-
-export function writeRetiredMarker({ root, operationId, marker }) {
-  const bytes = semanticBytes(marker);
-  const retirementId = semanticId(marker);
-  const path = retiredMarkerPath(root, operationId);
-  writeImmutableBytes(path, bytes);
-  return Object.freeze({ retirementId, marker: Object.freeze(marker), bytes, path });
-}
-
-export function readRetiredMarker({ root, operationId, normalize }) {
-  const path = retiredMarkerPath(root, operationId);
-  if (lstatSync(path).isSymbolicLink()) throw new Error("retired-marker-drift");
-  const bytes = readFileSync(path);
-  const marker = normalize(decodeSemantic(bytes));
-  if (!Buffer.from(semanticBytes(marker)).equals(bytes)) {
-    throw new Error("retired-marker-drift");
-  }
-  return Object.freeze({
-    retirementId: semanticId(marker),
-    marker,
-    bytes,
-    path,
-  });
-}
-
-function appendDurably(path, value) {
-  const index = readJournal(path).length;
-  writeImmutable(join(path, `${String(index).padStart(8, "0")}.json`), value);
-}
-
-export function profileHistory({ root, operationId }) {
-  return Object.freeze(
-    readJournal(journalPath(root, operationId)).map(Object.freeze),
-  );
-}
-
-export function beginProfileOperation({
-  root,
-  operationId,
-  requestId,
-  admittedAt = new Date().toISOString(),
-}) {
-  const path = journalPath(root, operationId);
-  const history = readJournal(path);
-  const prior = history.at(-1);
-  if (prior) {
-    if (prior.requestId !== requestId) throw new Error("operation-replay");
-    return Object.freeze({ replay: true, record: Object.freeze(prior) });
-  }
-  const record = {
-    version: 1,
-    operationId,
-    requestId,
-    admittedAt,
-    state: "admitted",
-    priorTransitionId: semanticId({
-      operationId,
-      state: "unobserved",
-    }),
-  };
-  record.transitionId = semanticId(record);
-  appendDurably(path, record);
-  return Object.freeze({ replay: false, record: Object.freeze(record) });
-}
-
-export function transitionProfileOperation({
-  root,
-  operationId,
-  requestId,
-  state,
-  receipt,
-  refusal,
-  proof,
-  deviceReceipt,
-}) {
-  const path = journalPath(root, operationId);
-  const prior = readJournal(path).at(-1);
-  if (!prior || prior.requestId !== requestId) throw new Error("operation-replay");
-  const edges = {
-    admitted: ["effect-started", "refused"],
-    "effect-started": ["completed", "refused", "unresolved"],
-  };
-  if (!edges[prior.state]?.includes(state)) throw new Error("invalid-transition");
-  const next = {
-    ...prior,
-    state,
-    priorTransitionId: prior.transitionId,
-  };
-  delete next.transitionId;
-  for (const [key, value] of Object.entries({
-    receipt,
-    refusal,
-    proof,
-    deviceReceipt,
-  })) {
-    if (value !== undefined) next[key] = value;
-  }
-  next.transitionId = semanticId(next);
-  appendDurably(path, next);
-  return Object.freeze(next);
-}
-
-export function recordDeviceReceipt({ root, operationId, effect, output }) {
-  const receipt = Object.freeze({
-    type: "BoundGitDeviceReceipt",
-    version: 1,
-    operationId,
-    effect,
-    output,
-  });
-  const id = semanticId(receipt);
-  const path = join(root, "device-receipts", `${token(id)}.json`);
-  const directory = dirname(path);
-  mkdirDurably(directory);
-  if (existsSync(path)) {
-    const existing = parseStoredJson(readFileSync(path, "utf8"));
-    if (semanticId(existing) !== id) throw new Error("device-receipt-identity-drift");
-    return Object.freeze({ id, receipt: Object.freeze(existing) });
-  }
-  writeImmutable(path, receipt);
-  return Object.freeze({ id, receipt });
-}

@@ -1,84 +0,0 @@
-#!/usr/bin/env node
-import { createHash } from 'node:crypto';
-import { normalizeRmnCarrier as rmnNormalizeCarrier, semanticBytes, semanticId, decodeSemantic } from '@red-cup-engineering/relation-model-notation-cbor-codec';
